<?php
require 'config/database.php';$pageTitle='Relatórios';$date=$_GET['date']??date('Y-m-d');
$s=$pdo->prepare("SELECT f.id,f.freight_date,f.status,t.name transporter,o.label origin,d.label destination,GROUP_CONCAT(CONCAT(p.name,' (',fp.quantity,')') SEPARATOR ', ') products FROM freights f JOIN transporters t ON t.id=f.transporter_id JOIN addresses o ON o.id=f.origin_id JOIN addresses d ON d.id=f.destination_id LEFT JOIN freight_products fp ON fp.freight_id=f.id LEFT JOIN products p ON p.id=fp.product_id WHERE f.freight_date=? GROUP BY f.id ORDER BY f.id");
$s->execute([$date]);$rows=$s->fetchAll();
if(isset($_GET['download'])){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="relatorio-fretes-'.$date.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Frete','Data','Transportador','Origem','Destino','Produtos','Status'],';');foreach($rows as $r)fputcsv($out,[$r['id'],$r['freight_date'],$r['transporter'],$r['origin'],$r['destination'],$r['products'],$r['status']],';');fclose($out);exit;}
require 'includes/header.php';?>
<h1 class="page-title">Relatórios</h1><p class="muted mb-4">Consulte e baixe os fretes realizados em uma data específica.</p>
<div class="card content-card"><form class="row g-3 align-items-end mb-4"><div class="col-md-4"><label class="form-label">Data dos fretes</label><input class="form-control" type="date" name="date" value="<?= htmlspecialchars($date) ?>"></div><div class="col-auto"><button class="btn btn-primary">Consultar</button></div><div class="col-auto"><a class="btn btn-outline-success" href="?date=<?= urlencode($date) ?>&download=1">Baixar relatório CSV</a></div></form>
<h5><?= date('d/m/Y',strtotime($date)) ?> — <?= count($rows) ?> frete(s)</h5><div class="table-responsive"><table class="table"><thead><tr><th>Nº</th><th>Transportador</th><th>Origem → Destino</th><th>Produtos</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td>#<?= $r['id'] ?></td><td><?= htmlspecialchars($r['transporter']) ?></td><td><?= htmlspecialchars($r['origin'].' → '.$r['destination']) ?></td><td><?= htmlspecialchars($r['products']??'') ?></td><td><?= htmlspecialchars($r['status']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="muted">Nenhum frete encontrado para essa data.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require 'includes/footer.php'; ?>
